    "All featured items meet strict CPSC, GOTS Organic, or European EN safety guidelines. Click any product to inspect full medical specifications, photo angles, and compare live pricing on Amazon India and Flipkart.": "அனைத்து பொருட்களும் கடுமையான பாதுகாப்பு வழிகாட்டுதல்களை பூர்த்தி செய்கின்றன. விவரங்களை காணவும் அமேசான்/பிளிப்கார்ட்டில் விலையை ஒப்பிடவும் கிளிக் செய்க.",
    "Search gear, brand, or item (e.g. Avent, stroller, crib, Sebamed)...": "பொருட்கள் அல்லது பிராண்டைத் தேடுங்கள் (எ.கா. ஸ்ட்ரோலர், தொட்டில், செபாமெட்)...",
