    "Prenatal Cat-Cow Spine Decompression": "முதுகுத்தண்டு தளர்வுக்கான பூனை-பசு ஆசனம்",
    "Mindful 20-Minute Prenatal Brisk Walk": "20 நிமிட சுறுசுறுப்பான நடைபயிற்சி",
    "Supported Birth Squats & Hip Openers": "பிரசவத்தை எளிதாக்கும் ஸ்குவாட்ஸ் பயிற்சிகள்",
    "Coherent 4-7-8 Labor Preparation Breathing": "4-7-8 பிரசவ முன் சுவாசப் பயிற்சி",
    "Strengthens the pubococcygeus hammock supporting your uterus, bladder, and bowel to prepare for birth and prevent postpartum incontinence.": "கருப்பை மற்றும் சிறுநீர்ப்பையை தாங்கும் இடுப்பு தசைகளை வலுப்படுத்துகிறது மற்றும் பிரசவத்திற்குப் பிந்தைய சிக்கல்களைத் தடுக்கிறது.",
    "Relieves lower back ache, improves spinal flexibility, and encourages baby into an optimal anterior birth position.": "முதுகுவலியை நீக்குகிறது, முதுகெலும்பு நெகிழ்வுத்தன்மையை மேம்படுத்துகிறது மற்றும் குழந்தை சரியான நிலைக்கு வர உதவுகிறது.",
    "Maintains cardiovascular fitness, regulates gestational blood sugar, and boosts natural mood-enhancing endorphins.": "இதய ஆரோக்கியத்தை பராமரிக்கிறது, இரத்த சர்க்கரையை கட்டுப்படுத்துகிறது மற்றும் மனநிலையை மேம்படுத்துகிறது.",
    "Expands the pelvic outlet by up to 30%, stretches the perineum, and utilizes gravity to guide the baby down.": "இடுப்பு பகுதியை 30% வரை விரிவுபடுத்துகிறது மற்றும் குழந்தை எளிதாக கீழே இறங்க உதவுகிறது.",
    "Activates the parasympathetic nervous system (vagus nerve), lowers cortisol, and primes maternal breathing instincts for labor contractions.": "நரம்பு மண்டலத்தை அமைதிப்படுத்துகிறது, மன அழுத்தத்தை குறைக்கிறது மற்றும் பிரசவ வலிக்கு சுவாசத்தை தயார்படுத்துகிறது.",
    "Sit comfortably on a chair or lie on your left side with knees bent.": "நாற்காலியில் சௌகரியமாக உட்காருங்கள் அல்லது முழங்கால்களை மடக்கி இடதுபுறமாக படுக்கவும்.",
    "Come onto hands and knees in a tabletop position with wrists under shoulders and knees under hips.": "கைகள் மற்றும் முழங்கால்களை ஊன்றி மேஜை வடிவில் நிற்கவும்.",
    "Put on supportive athletic shoes with cushioned arches.": "சௌகரியமான காலணிகளை அணியுங்கள்.",
    "Stand facing a sturdy chair, wall, or holding hands with your partner.": "நாற்காலி அல்லது சுவரைப் பிடித்து நிற்கவும் அல்லது உங்கள் துணையின் கைகளைப் பிடிக்கவும்.",
    "Sit comfortably supported with pillows or lie on your left side.": "தலையணைகளின் ஆதரவுடன் அமரவும் அல்லது இடதுபுறமாக படுக்கவும்.",
    "Mindful Walking Tracker": "தினசரி நடைபயிற்சி டிராக்கர்",
