    "vaultTitle": "அரிய தருணங்கள் & ஸ்கேன் பெட்டகம்",
    "vaultSubtitle": "அல்ட்ராசவுண்ட் ஸ்கேன்கள், புகைப்படங்கள் மற்றும் நினைவுகளுக்கான தனிப்பட்ட ஆல்பம்.",
    "Diagnostic Imagery Disclaimer": "மருத்துவ பட மறுப்பு",
    "vaultDisclaimer": "கவனிக்க: இங்குள்ள படங்கள் தனிப்பட்ட நினைவுகளுக்காக மட்டுமே; முறையான மருத்துவ அறிக்கைகளுக்கு மாற்றாகாது.",
