    "Export Scrapbook": "ஆல்பத்தை பதிவிறக்கு",
    "Download Scrapbook Export": "ஆல்பத்தை பதிவிறக்கு",
    "uploadScan": "ஸ்கேன் / புகைப்படம் சேர்க்க",
    "First Trimester NT Scan": "முதல் பருவ NT ஸ்கேன்",
    "We saw tiny hands waving and heard a strong 158 bpm heartbeat!": "சிறிய கைகள் அசைவதைக் கண்டோம், 158 bpm இதயத் துடிப்பைக் கேட்டோம்!",
    "Nuchal translucency measurement: 1.4 mm (Normal range). Dr. Sunita confirmed healthy cranial and spine structure.": "நியூக்கல் டிரான்ஸ்லூசென்சி: 1.4 மிமீ (இயல்பு). தலை மற்றும் முதுகுத்தண்டு ஆரோக்கியமாக இருப்பதாக மருத்துவர் உறுதிப்படுத்தினார்.",
    "Crown-rump length exactly matches 11w4d. Placenta posterior, high.": "நீளம் 11 வாரம் 4 நாட்களுக்கு சரியாக பொருந்துகிறது. பிளசன்டா இயல்பாக உள்ளது.",
    "Mid-Pregnancy Level II Anomaly Scan": "இரண்டாம் பருவ நிலை II ஸ்கேன்",
    "All four chambers of the heart, kidneys, ten tiny fingers, and cutest profile!": "இதயத்தின் நான்கு அறைகள், சிறுநீரகங்கள் மற்றும் பத்து விரல்கள் தெளிவாகத் தெரிந்தன!",
    "Detailed anatomical scan clear. Baby yawned twice during the ultrasound!": "அமைப்பு ஸ்கேன் மிகச் சிறப்பானது. ஸ்கேன் போது குழந்தை இரண்டு முறை கொட்டாவி விட்டது!",
    "Amniotic fluid index 14 cm. Cervical length 3.8 cm (Normal). Estimated fetal weight 340g.": "பனிக்குட நீர் குறியீடு 14 செ.மீ. கர்ப்பப்பை வாய் நீளம் 3.8 செ.மீ. எடை 340 கிராம்.",
    "First Time Rohan Felt the Kicks!": "முதல்முறையாக துணைவர் குழந்தையின் உதைப்பை உணர்ந்தார்!",
    "We were sitting on the couch listening to ocean waves and baby did three big kicks right against Rohan's palm.": "நாங்கள் அமர்ந்திருந்தபோது குழந்தை ரோஹனின் உள்ளங்கையில் மூன்று முறை எட்டி உதைத்தது.",
    "A memory we will cherish forever. Rohan got so teary-eyed.": "நாங்கள் என்றும் போற்றும் ஒரு இனிய நினைவு.",
    "Doctor's Observation:": "மருத்துவரின் குறிப்பு:",
