    "The Fourth Trimester Maternal Recovery": "நான்காவது பருவம்: பிரசவத்திற்குப் பிந்தைய தாய் நலம்",
    "postpartumTitle": "பிரசவத்திற்குப் பிந்தைய பராமரிப்பு டாஷ்போர்டு",
    "postpartumSubtitle": "பிரசவத்திற்குப் பின் இரத்தப்போக்கு, காயம் குணமடைதல், தாய்ப்பால் மற்றும் மன அமைதி கண்காணிப்பு.",
    "Baby Born (Postpartum Active)": "குழந்தை பிறந்தது (பிரசவத்திற்குப் பிந்தைய நிலை)",
    "Pregnancy Stage (Previewing Postpartum)": "கர்ப்பகால நிலை (முன்னோட்டம்)",
    "Emergency Postpartum Red Flags": "அவசர பிரசவத்திற்குப் பிந்தைய எச்சரிக்கை அறிகுறிகள்",
    "Seek immediate emergency care (112 / 911 / 108) if you experience: Heavy vaginal bleeding, severe chest pain or shortness of breath, persistent severe headache, or fever.": "அதிக இரத்தப்போக்கு, நெஞ்சுவலி, மூச்சுத்திணறல் அல்லது காய்ச்சல் இருந்தால் உடனடியாக அவசர சிகிச்சை (112 / 108) பெறவும்.",
    "Daily Maternal Recovery Log": "தினசரி தாய் நலம் பதிவு",
    "Delivery Type": "பிரசவ வகை",
    "Vaginal Birth": "இயற்கை பிரசவம்",
    "Cesarean (C-Section)": "சிசேரியன் (அறுவை சிகிச்சை)",
