    "Moderate Red (Normal Days 3-10)": "மிதமான சிவப்பு (இயல்பு நாட்கள் 3-10)",
    "Heavy (Soaking 1 pad / 2 hrs)": "அதிகம் (2 மணி நேரத்தில் 1 பேட்)",
    "Emergency: Soaking < 1 hr or big clots": "அவசரம்: 1 மணி நேரத்திற்குள் நனைதல் அல்லது பெரிய கட்டிகள்",
    "Breast Condition": "மார்பக நிலை",
