    "Engorged & Full": "நிறைந்த / இறுக்கமான நிலை",
    "Tender or Sore Nipples": "வலி மிகுந்த காம்புகள்",
    "High Fever & Red Hard Streaks": "கடும் காய்ச்சல் மற்றும் சிவந்த கோடுகள்",
    "Sleep Total (Hours)": "மொத்த தூக்கம் (மணிநேரம்)",
    "Emotional Wellbeing (1-10)": "மனநலம் (1-10)",
    "Daily Recovery Notes & Questions for Midwife": "தினசரி குறிப்புகள் மற்றும் மருத்துவரிடம் கேட்க வேண்டியவை",
    "e.g. Incision itching normally, baby feeding every 2.5 hours...": "எ.கா. தையல் அரிப்பு இயல்பாக உள்ளது, குழந்தை 2.5 மணி நேரத்திற்கு ஒரு முறை பால் குடிக்கிறது...",
    "Save Postpartum Check-In": "பதிவைச் சேமிக்கவும்",
    "The 6-Week Recovery Milestones": "6-வார நலம் பெரும் மைல்கற்கள்",
    "Days 1 - 7: Immediate Involution": "நாட்கள் 1 - 7: கருப்பை சுருங்குதல்",
    "Uterus contracts back toward pelvic bone with cramp-like afterpains (encouraged by breastfeeding oxytocin). Colostrum transitions to mature milk around day 3-5.": "கருப்பை மீண்டும் இயல்பு நிலைக்கு சுருங்குகிறது. தாய்ப்பால் கொடுப்பது இதற்கு பெரிதும் உதவுகிறது.",
    "Weeks 2 - 4: Healing & Gentle Rhythm": "வாரங்கள் 2 - 4: குணமாகுதல் & ஓய்வு",
    "Lochia lightens from bright red (rubra) to pinkish-yellow (serosa/alba). Rest is non-negotiable: limit stairs and heavy lifting.": "இரத்தப்போக்கு குறைகிறது. படிகள் ஏறுவதையும் கனமான பொருட்களை தூக்குவதையும் தவிர்க்கவும்.",
