    "caregiverSyncSub": "பிரசவ வலி நேரம், உதை எண்ணுதல் மற்றும் வாராந்திர பணிகள் ஒத்திசைக்கப்பட்டுள்ளன.",
    "Labor surge timing, kick counting, and weekly caregiver missions are synchronized.": "பிரசவ வலி நேரம், உதை எண்ணுதல் மற்றும் வாராந்திர பணிகள் ஒத்திசைக்கப்பட்டுள்ளன.",
    "unpairedCaregiverSub": "தாய் அனுமதியளிக்கும் வரை அனைத்து மருத்துவ ஆவணங்களும் பாதுகாப்பாக வைக்கப்படும்.",
    "Maternal records remain isolated until authorized by an eligible expecting mother.": "தாய் அனுமதியளிக்கும் வரை அனைத்து மருத்துவ ஆவணங்களும் பாதுகாப்பாக வைக்கப்படும்.",
    "dataSequesteredTitle": "தகவல் பாதுகாக்கப்பட்டுள்ளது · இணைக்கப்படாத துணைவர் கணக்கு",
    "Data Sequestered · Unpaired Partner Account": "தகவல் பாதுகாக்கப்பட்டுள்ளது · இணைக்கப்படாத துணைவர் கணக்கு",
    "dataSequesteredDesc": "தாயின் மருத்துவ ஆவணங்கள் கிரிப்டோகிராபிக் முறையில் பாதுகாக்கப்பட்டுள்ளன. துணைவர் குறியீட்டை உள்ளிடவும்.",
    "Maternal clinical records, ultrasounds, and vitals are protected by cryptographic account isolation. Enter your partner\\'s code below or choose an available mother.": "தாயின் மருத்துவ ஆவணங்கள் கிரிப்டோகிராபிக் முறையில் பாதுகாக்கப்பட்டுள்ளன. துணைவர் குறியீட்டை உள்ளிடவும்.",
