    "Coherent 4-7-8 Labor Preparation Breathing": "4-7-8 ప్రసవ పూర్వ శ్వాస పద్ధతి",
    "Strengthens the pubococcygeus hammock supporting your uterus, bladder, and bowel to prepare for birth and prevent postpartum incontinence.": "గర్భాశయం మరియు మూత్రాశయానికి మద్దతు ఇచ్చే పెల్విక్ కండరాలను బలపరుస్తుంది మరియు ప్రసవానంతర సమస్యలను నివారిస్తుంది.",
    "Relieves lower back ache, improves spinal flexibility, and encourages baby into an optimal anterior birth position.": "నడుము నొప్పిని తగ్గిస్తుంది, వెన్నెముకను దృఢపరుస్తుంది మరియు బిడ్డ సరైన స్థానానికి రావడానికి సహాయపడుతుంది.",
    "Maintains cardiovascular fitness, regulates gestational blood sugar, and boosts natural mood-enhancing endorphins.": "గుండె ఆరోగ్యాన్ని కాపాడుతుంది, రక్తంలో చక్కెరను నియంత్రిస్తుంది మరియు ఉత్తేజాన్ని ఇస్తుంది.",
    "Expands the pelvic outlet by up to 30%, stretches the perineum, and utilizes gravity to guide the baby down.": "పెల్విక్ భాగాన్ని 30% వరకు విస్తరింపజేస్తుంది మరియు బిడ్డ సులభంగా క్రిందికి రావడానికి తోడ్పడుతుంది.",
    "Activates the parasympathetic nervous system (vagus nerve), lowers cortisol, and primes maternal breathing instincts for labor contractions.": "నాడీ వ్యవస్థను ప్రశాంతపరుస్తుంది, ఆందోళనను తగ్గిస్తుంది మరియు ప్రసవ నొప్పుల శ్వాసకు సిద్ధం చేస్తుంది.",
    "Sit comfortably on a chair or lie on your left side with knees bent.": "కుర్చీలో సౌకర్యవంతంగా కూర్చోండి లేదా మోకాళ్ళను మడిచి ఎడమవైపుకు పడుకోండి.",
    "Come onto hands and knees in a tabletop position with wrists under shoulders and knees under hips.": "చేతులు, మోకాళ్ళపై టేబుల్ పొజిషన్‌లో ఉండండి.",
    "Put on supportive athletic shoes with cushioned arches.": "సౌకర్యవంతమైన బూట్లు ధరించండి.",
    "Stand facing a sturdy chair, wall, or holding hands with your partner.": "కుర్చీ లేదా గోడను పట్టుకుని నిలబడండి లేదా భాగస్వామి చేతులు పట్టుకోండి.",
    "Sit comfortably supported with pillows or lie on your left side.": "దిండ్ల ఆసరా తీసుకుని కూర్చోండి లేదా ఎడమవైపుకు పడుకోండి.",
