    "Detailed anatomical scan clear. Baby yawned twice during the ultrasound!": "స్కాన్ చాలా స్పష్టంగా వచ్చింది. స్కాన్ సమయంలో బిడ్డ రెండుసార్లు ఆవులించింది!",
    "Amniotic fluid index 14 cm. Cervical length 3.8 cm (Normal). Estimated fetal weight 340g.": "ఉల్బద్రవ సూచిక 14 సెం.మీ. గర్భాశయ ముఖద్వార పొడవు 3.8 సెం.మీ. బరువు 340 గ్రా.",
    "First Time Rohan Felt the Kicks!": "మొదటిసారి భాగస్వామి బిడ్డ తన్నులను అనుభవించారు!",
    "We were sitting on the couch listening to ocean waves and baby did three big kicks right against Rohan's palm.": "మేము కూర్చుని ఉన్నప్పుడు బిడ్డ రోహన్ అరచేతిపై మూడుసార్లు బలంగా తన్నింది.",
