    "Strengthens the pubococcygeus hammock supporting your uterus, bladder, and bowel to prepare for birth and prevent postpartum incontinence.": "ഗർഭാശയത്തെയും മൂത്രസഞ്ചിയെയും താങ്ങിനിർത്തുന്ന പെൽവിക് പേശികളെ ശക്തിപ്പെടുത്തുകയും പ്രസവാനന്തര പ്രശ്നങ്ങൾ തടയുകയും ചെയ്യുന്നു.",
    "Relieves lower back ache, improves spinal flexibility, and encourages baby into an optimal anterior birth position.": "നടുവേദന മാറ്റുന്നു, നട്ടെല്ലിന്റെ വഴക്കം വർദ്ധിപ്പിക്കുന്നു, കുഞ്ഞിന് അനുയോജ്യമായ സ്ഥാനം നൽകുന്നു.",
    "Maintains cardiovascular fitness, regulates gestational blood sugar, and boosts natural mood-enhancing endorphins.": "ഹൃദയാരോഗ്യം നിലനിർത്തുന്നു, രക്തത്തിലെ പഞ്ചസാരയുടെ അളവ് നിയന്ത്രിക്കുന്നു.",
    "Expands the pelvic outlet by up to 30%, stretches the perineum, and utilizes gravity to guide the baby down.": "പെൽവിക് വിസ്തൃതി 30% വരെ വർദ്ധിപ്പിക്കുകയും കുഞ്ഞിന് താഴേക്ക് വരാൻ എളുപ്പമാക്കുകയും ചെയ്യുന്നു.",
    "Activates the parasympathetic nervous system (vagus nerve), lowers cortisol, and primes maternal breathing instincts for labor contractions.": "നാഡീവ്യൂഹത്തെ ശാന്തമാക്കുന്നു, ഉത്കണ്ഠ കുറയ്ക്കുന്നു, പ്രസവ വേദനയെ നേരിടാൻ സഹായിക്കുന്നു.",
    "Sit comfortably on a chair or lie on your left side with knees bent.": "കസേരയിൽ സുഖമായി ഇരിക്കുക അല്ലെങ്കിൽ ഇടത് വശത്തേക്ക് ചരിഞ്ഞ് കിടക്കുക.",
    "Come onto hands and knees in a tabletop position with wrists under shoulders and knees under hips.": "കൈകളും കാൽമുട്ടുകളും നിലത്തുറപ്പിച്ച് നിൽക്കുക.",
    "Put on supportive athletic shoes with cushioned arches.": "സുഖകരമായ പാദരക്ഷകൾ ധരിക്കുക.",
    "Stand facing a sturdy chair, wall, or holding hands with your partner.": "ഒരു കസേരയിലോ ചുവരിലോ പിടിക്കുക അല്ലെങ്കിൽ പങ്കാളിയുടെ കൈകൾ പിടിക്കുക.",
    "Sit comfortably supported with pillows or lie on your left side.": "തലയിണകളുടെ സഹായത്തോടെ ഇരിക്കുക അല്ലെങ്കിൽ ഇടത് വശത്തേക്ക് ചരിഞ്ഞ് കിടക്കുക.",
