    "First Trimester NT Scan": "ഒന്നാം ത്രിമാസ NT സ്കാൻ",
    "We saw tiny hands waving and heard a strong 158 bpm heartbeat!": "കുഞ്ഞു കൈകൾ ചലിക്കുന്നത് കണ്ടു, 158 bpm ഹൃദയമിടിപ്പ് കേട്ടു!",
    "Nuchal translucency measurement: 1.4 mm (Normal range). Dr. Sunita confirmed healthy cranial and spine structure.": "ന്യൂക്കൽ ട്രാൻസ്ലൂസെൻസി: 1.4 മി.മീ (സാധാരണ നില). തലയും നട്ടെല്ലും ആരോഗ്യകരമാണെന്ന് ഡോക്ടർ സ്ഥിരീകരിച്ചു.",
    "Crown-rump length exactly matches 11w4d. Placenta posterior, high.": "നീളം 11 ആഴ്ച 4 ദിവസത്തിന് കൃത്യമാണ്. പ്ലാസന്റ സാധാരണ നിലയിലാണ്.",
