    "All four chambers of the heart, kidneys, ten tiny fingers, and cutest profile!": "ഹൃദയത്തിന്റെ നാല് അറകളും വൃക്കകളും പത്ത് വിരലുകളും വ്യക്തമായി കണ്ടു!",
    "Detailed anatomical scan clear. Baby yawned twice during the ultrasound!": "സ്കാൻ വളരെ വ്യക്തമാണ്. സ്കാനിംഗിനിടെ കുഞ്ഞ് രണ്ടുതവണ കോട്ടുവായിട്ടു!",
    "Amniotic fluid index 14 cm. Cervical length 3.8 cm (Normal). Estimated fetal weight 340g.": "അമ്നിയോട്ടിക് ദ്രാവകം 14 സെ.മീ. സെർവിക്കൽ നീളം 3.8 സെ.മീ. ഭാരം 340 ഗ്രാം.",
    "First Time Rohan Felt the Kicks!": "ആദ്യമായി പങ്കാളി കുഞ്ഞിന്റെ ചവിട്ട് അറിഞ്ഞു!",
    "We were sitting on the couch listening to ocean waves and baby did three big kicks right against Rohan's palm.": "ഞങ്ങൾ ഇരിക്കുമ്പോൾ കുഞ്ഞ് രോഹന്റെ കൈവെള്ളയിൽ മൂന്ന് തവണ ശക്തമായി ചവിട്ടി.",
    "A memory we will cherish forever. Rohan got so teary-eyed.": "ഞങ്ങൾ എന്നും ഓർത്തിരിക്കുന്ന ഒരു മനോഹര നിമിഷം.",
