    "Seek immediate emergency care (112 / 911 / 108) if you experience: Heavy vaginal bleeding, severe chest pain or shortness of breath, persistent severe headache, or fever.": "അമിത രക്തസ്രാവം, നെഞ്ചുവേദന, ശ്വാസതടസ്സം അല്ലെങ്കിൽ പനി അനുഭവപ്പെടുകയാണെങ്കിൽ ഉടൻ അടിയന്തര ചികിത്സ (112 / 108) തേടുക.",
